import{z as A,x as o,o as n,c as T,q as i,j as r,D as t,d as e,s as B,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"测试时训练","description":"","frontmatter":{"title":"测试时训练","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/continual-test-time-training.md","filePath":"llm/continual-test-time-training.md","lastUpdated":1791413859000}'),d={name:"llm/continual-test-time-training.md"};function p(m,a,D,u,h,c){const l=o("Mermaid");return n(),T("div",null,[a[2]||(a[2]=i('<h1 id="测试时训练" tabindex="-1">测试时训练 <a class="header-anchor" href="#测试时训练" aria-label="Permalink to &quot;测试时训练&quot;">​</a></h1><div class="epigraph"><p>有些适配不必活过这一次请求：在上下文上走几步梯度，回答完就扔，学习与部署的边界在单次推理内部消失。</p><footer>—— 据 Hardt 与 Sun 2023、Akyürek 等 2024 整理</footer></div><p><a href="/llm/continual-online-preference">上一课</a>把更新节奏压到流式，但每次更新仍是全局的、要发布的。测试时训练（TTT）把学习再压一层：在<strong>单次请求内部</strong>对临时副本走几步梯度，让这次预测适配该实例的分布，请求结束即丢弃。它是持续学习谱系里寿命最短的一档——从月级发布到流式更新，再到请求级、一次性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两个场景暴露同一缺口。其一，长上下文塞满用户私有材料：提示里有模式可学，但纯前向的少样本推理对模式利用有限，注意力每一步都要重读示例。其二，任务族迁移：一组结构全新但自洽的谜题，各带几个示例，全局模型没见过这个分布，也不值得为它发版权重。共同点：适配范围就是本次请求，时间预算就是延迟预算。</p><h3 id="与相邻概念划界" tabindex="-1">与相邻概念划界 <a class="header-anchor" href="#与相邻概念划界" aria-label="Permalink to &quot;与相邻概念划界&quot;">​</a></h3><p><a href="/llm/test-time-scaling">Test-time compute scaling</a>讲的是推理期算力换质量——更多采样、更长思考、投票选择，权重始终不动。TTT 恰恰相反：几乎不多采样，动的是权重，只是动完就扔。<a href="/llm/titans-test-time-memory">Titans 测试时记忆</a>把测试时更新做进架构，记忆随序列持久演化；本课的 TTT 是无架构改动的临时外挂。三者的公共直觉是「推理期资源可换质量」，差别在资源落在 logits、权重还是记忆上。</p><p><span class="marginnote">Hardt 与 Sun 2023 的做法：检索与查询相似的样本，在它们上面做若干梯度步再回答；Akyürek 等 2024 用「增强示例、临时微调、采样投票」在 ARC 类谜题上拿到显著增益。两条线的共同点是训练信号全部来自本次请求内部。</span></p><p><span class="marginnote">「少样本推理」是把示例放进提示，让注意力「照着读」；TTT 是把这些示例真的当成训练集去走反向传播。区别好比「看着菜谱做菜」和「先背下菜谱再闭卷做」——后者记得更牢，但多花一道工。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>无架构版 TTT 的流水线：从请求内部构造训练集——长上下文取检索近邻，谜题取自带示例；把「预测某示例的答案、其余当训练数据」写成损失；在冻结基座上临时训练适配器，走 \\(n\\) 步小学习率梯度；用它生成回答；请求结束即丢弃。\\(n\\) 与学习率是本次请求的私有超参：任务越偏离全局分布，越值得多走几步。</p>',11)),(n(),r(s,null,{default:t(()=>[B(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%EF%BC%88%E9%95%BF%E4%B8%8A%E4%B8%8B%E6%96%87%2F%E8%B0%9C%E9%A2%98%EF%BC%89%22%5D%20--%3E%20BUILD%5B%22%E4%BB%8E%E8%AF%B7%E6%B1%82%E5%86%85%E9%83%A8%E6%9E%84%E9%80%A0%E8%AE%AD%E7%BB%83%E9%9B%86%22%5D%0A%20%20BUILD%20--%3E%20TMP%5B%22%E5%86%BB%E7%BB%93%E5%9F%BA%E5%BA%A7%2B%E4%B8%B4%E6%97%B6%E9%80%82%E9%85%8D%E5%99%A8%22%5D%0A%20%20TMP%20--%3E%20STEP%5B%22%E8%B5%B0%20n%20%E6%AD%A5%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20STEP%20--%3E%20GEN%5B%22%E7%94%A8%E4%B8%B4%E6%97%B6%E9%80%82%E9%85%8D%E5%99%A8%E7%94%9F%E6%88%90%E5%9B%9E%E7%AD%94%22%5D%0A%20%20GEN%20--%3E%20DROP%5B%22%E8%AF%B7%E6%B1%82%E7%BB%93%E6%9D%9F%EF%BC%9A%E4%B8%A2%E5%BC%83%EF%BC%8C%E4%B8%8D%E7%95%99%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"几步梯度改变什么：条件分布被显式朝上下文内模式压紧。少样本推理是隐式的上下文内学习——前向一遍，效果封顶；TTT 换成显式优化，同一笔信息从「注意」升级为「反向传播」，是第二遍、更贵的读取。收益上限由上下文质量决定：训练集噪声大，几步梯度就是几步过拟合。",-1)),a[5]||(a[5]=E("p",null,[e("丢弃是特性不是缺陷：适配器不落盘，用户之间零串扰，隐私口径最干净——与"),E("a",{href:"/llm/continual-online-preference"},"在线偏好更新"),e("的持久更新构成谱系两端，要积累走后者，要隔离走前者。代价结构不同：TTT 把成本从训练管线挪到请求延迟，每次多付 \\(n\\) 次反传的时延与显存，高峰期直接进 SLO。")],-1)),a[6]||(a[6]=E("p",null,"把整条「适配寿命」的谱系排开，TTT 的位置一目了然：",-1)),(n(),r(s,null,{default:t(()=>[B(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E9%9D%99%E6%80%81%E6%A8%A1%E5%9E%8B%3A%E6%9D%83%E9%87%8D%E6%B0%B8%E4%B8%8D%E5%8A%A8%22%5D%20--%3E%20B%5B%22%E6%8E%A8%E7%90%86%E6%9C%9F%E7%BC%A9%E6%94%BE%3A%E5%A4%9A%E9%87%87%E6%A0%B7%E5%A4%9A%E6%80%9D%E8%80%83%2C%E6%9D%83%E9%87%8D%E4%BB%8D%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20B%20--%3E%20C%5B%22TTT%3A%E8%AF%B7%E6%B1%82%E5%86%85%E4%B8%B4%E6%97%B6%E6%94%B9%E6%9D%83%E9%87%8D%2C%E7%94%A8%E5%AE%8C%E5%8D%B3%E5%BC%83%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%9C%A8%E7%BA%BF%E6%9B%B4%E6%96%B0%3A%E5%85%A8%E5%B1%80%E6%8C%81%E4%B9%85%E6%94%B9%E6%9D%83%E9%87%8D%22%5D%0A%20%20A%20-.%20%22%E9%9A%94%E7%A6%BB%E6%80%A7%E9%80%92%E5%87%8F%2C%E7%A7%AF%E7%B4%AF%E6%80%A7%E9%80%92%E5%A2%9E%22%20.-%3E%20D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p><span class="marginnote">数字感受一下延迟代价：走 \\(n=20\\) 步梯度，等于在正式回答前先做 20 次反向传播，单请求可能多付几百毫秒到数秒。如果服务的延迟目标定在 1 秒内，这笔账只有高价值请求付得起。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>延迟是硬边界：\\(n\\) 步反传加临时适配器的开销把 TTT 挡在高价值请求之外，全量流量上不起。过拟合是质量边界：训练集只有几个样本时，梯度步数与学习率的扫描本身就是过拟合扫描，产出必须与「零步基线」在同算力预算下对比，否则测到的是多花的算力而不是适配。状态边界要看清：默认不积累，若把某用户的临时适配器缓存复用，就进入了持久学习——跨请求泄漏、删除义务、版本管理全套问题随之而来，等于选回了上一课的模式。</p><p>任务分布稳定时不值得 TTT：全局模型覆盖得住的分布，检索与少样本已够。TTT 的适用面是「分布新、自洽、单次」三条件同时成立。最后，评测 TTT 要防自我实现：如果构造训练集的方式泄露了测试目标，涨的不是适配能力，是数据泄漏。</p><p><span class="marginnote">常见误区：以为「适配器只缓存、不训练」就没沾持续学习的麻烦。只要它跨请求存活，用户 A 的私有材料就可能经适配器影响用户 B 的回答——串扰、删除义务、版本管理，全套问题一样不少地回来了。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TTT 把学习压进单次请求：临时副本走几步梯度，回答后丢弃，是持续学习谱系里寿命最短的档位。</li><li>与推理期缩放划界：后者加采样不动权重；TTT 动权重但几乎不加采样。</li><li>训练信号全部来自请求内部，收益上限由上下文质量决定，噪声训练集等于付费过拟合。</li><li>丢弃带来零跨请求泄漏，隐私口径最干净；成本结构是把训练预算换成请求延迟。</li><li>要积累走在线更新，要隔离走 TTT；缓存临时适配器即回到持久学习的全套义务。</li><li>出处：Hardt 与 Sun 2023（检索近邻做 TTT）；Akyürek 等 2024（ARC 上的 TTT）；Sun 等 2020 的测试时学习层谱系。</li></ul>',7))])}const _=A(d,[["render",p]]);export{C as __pageData,_ as default};
